const mongoose = require('mongoose');

const voiceRecordSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
      index: true
    },
    mediaId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'MediaUpload'
    },
    audioFileName: {
      type: String,
      default: 'live_voice.wav'
    },
    audioDurationSec: {
      type: Number,
      default: 0
    },
    // Transcribed English text generated by local Whisper AI model
    transcript: {
      type: String,
      required: true,
      trim: true
    },
    wordCount: {
      type: Number,
      default: 0
    },
    speechConfidence: {
      type: Number,
      default: 0.85,
      min: 0,
      max: 0.90 // Capped at 0.90 per Section 9.1 Mandate
    },
    speechModel: {
      type: String,
      default: 'Xenova/whisper-tiny.en (Local ONNX Runtime)'
    },
    // Acoustic biometric & synthetic voice analysis
    acousticAnalysis: {
      spectralFlatness: { type: Number, default: 0 },
      spectralCentroid: { type: Number, default: 0 },
      spectralRolloff: { type: Number, default: 0 },
      energy: { type: Number, default: 0 },
      livenessScore: { type: Number, default: 100 },
      speakerMatchScore: { type: Number, default: 100 },
      isSyntheticVoice: { type: Boolean, default: false }
    },
    // Social engineering & threat detection evaluated on recognized transcript
    transcriptRisk: {
      verdict: {
        type: String,
        enum: ['safe', 'suspicious', 'malicious', 'inconclusive'],
        default: 'safe'
      },
      score: {
        type: Number,
        default: 0,
        min: 0,
        max: 100
      },
      indicators: [
        {
          name: { type: String, required: true },
          value: { type: mongoose.Schema.Types.Mixed },
          weight: { type: Number },
          explanation: { type: String, required: true }
        }
      ]
    },
    // Combined forensic assessment
    combinedVerdict: {
      type: String,
      enum: ['authentic', 'safe', 'suspicious', 'malicious', 'inconclusive'],
      default: 'safe'
    },
    combinedRiskScore: {
      type: Number,
      default: 0,
      min: 0,
      max: 100
    },
    processingMs: {
      type: Number,
      default: 0
    },
    status: {
      type: String,
      enum: ['completed', 'failed'],
      default: 'completed'
    },
    disclaimer: {
      type: String,
      default: 'Automated AI speech transcription and screening assists human investigators and does not constitute a legal verdict.'
    }
  },
  { timestamps: true }
);

voiceRecordSchema.index({ userId: 1, createdAt: -1 });
voiceRecordSchema.index({ combinedVerdict: 1 });

module.exports = mongoose.model('VoiceRecord', voiceRecordSchema);
